@Test
public void testVariableMap_1_oe() throws Exception {
    final JexlScript script = JEXL.createScript("{ ['1', '2'.toString()] : someValue }", "someValue");
    final Object result = script.execute(null, 42);
    Assert.assertTrue(result instanceof Map);
}

@Test
public void testVariableMap_2_oe() throws Exception {
    final JexlScript script = JEXL.createScript("{ ['1', '2'.toString()] : someValue }", "someValue");
    final Object result = script.execute(null, 42);
    // removed other assertion
    Object key = null;
    Object value = null;
    for(final Map.Entry<?,?> e : ((Map<?,?>) result).entrySet()) {
        key = e.getKey();
        value = e.getValue();
        break;
    }
    final Object gg = ((Map) result).get(key);
    Assert.assertEquals(42, ((Number) gg).intValue());
}

@Test
public void testVariableMap_3_oe() throws Exception {
    final JexlScript script = JEXL.createScript("{ ['1', '2'.toString()] : someValue }", "someValue");
    final Object result = script.execute(null, 42);
    // removed other assertion
    Object key = null;
    Object value = null;
    for(final Map.Entry<?,?> e : ((Map<?,?>) result).entrySet()) {
        key = e.getKey();
        value = e.getValue();
        break;
    }
    final Object gg = ((Map) result).get(key);
    // removed other assertion
    Assert.assertEquals(value, ((Number) gg).intValue());
}

@Test
@SuppressWarnings("unchecked")
public void testInterval_1_oe() throws Exception {
    final Map<String, Object> ns = new HashMap<String, Object>();
    ns.put("calc", Aggregate.class);
    final JexlEngine jexl = new JexlBuilder().namespaces(ns).create();
    JexlScript script;
    Object result;

    script = jexl.createScript("1 .. 3");
    result = script.execute(null);
    Assert.assertTrue(result instanceof Iterable<?>);
}

